let state={destination:'US',cart:[],wishlist:[],search:'',category:'All',origin:'All',sort:'featured',maxPrice:1000,delivery:'express',dashboard:'overview',adminTab:'overview',submitted:false,extraProducts:[],vendorStatus:{},productStatus:{},commissions:12,selectedImage:0};
try{const saved=JSON.parse(localStorage.getItem('dutyfree-demo')||'null');if(saved){state.destination=countries[saved.destination]?saved.destination:'US';state.cart=Array.isArray(saved.cart)?saved.cart.filter(i=>products.some(p=>p.id===i.id)&&Number.isInteger(i.qty)&&i.qty>0&&i.qty<=10):[];state.wishlist=Array.isArray(saved.wishlist)?saved.wishlist.filter(id=>products.some(p=>p.id===id)):[];}}catch{}
const save=()=>{try{localStorage.setItem('dutyfree-demo',JSON.stringify({destination:state.destination,cart:state.cart,wishlist:state.wishlist}));}catch{}};
const product=id=>products.find(p=>p.id===id);
const photoSrc=p=>p.photo||`./assets/${p.image}`;
const net=p=>p.price-p.discount;
function estimate(items,service=state.delivery){const destination=countries[state.destination];const groups={};items.forEach(i=>{const p=product(i.id);if(p)(groups[p.vendor]??=[]).push({...p,qty:i.qty});});let subtotal=0,discount=0,shipping=0;const shipments=Object.entries(groups).map(([vendor,items])=>{let value=0,weight=0,volumetric=0;items.forEach(p=>{subtotal+=p.price*p.qty;discount+=p.discount*p.qty;value+=net(p)*p.qty;weight+=p.weight*p.qty;const dims=p.dimensions.split(' × ').map(s=>parseFloat(s));volumetric+=dims.reduce((a,b)=>a*b,1)/5000*p.qty;});const domestic=items.every(p=>p.code===state.destination);const billable=Math.max(weight,volumetric);const fee=Math.round(((domestic?8:16)+billable*(service==='express'?4.5:2.9))*(service==='express'?1:0.85)*100)/100;shipping+=fee;return{vendor,items,shipping:fee,weight,billable,value};});const duty=Math.round((subtotal-discount)*destination.duty*100)/100;const tax=Math.round((subtotal-discount+shipping+duty)*destination.tax*100)/100;return{subtotal,discount,shipping,duty,tax,total:subtotal-discount+shipping+duty+tax,shipments};}
const delivered=p=>estimate([{id:p.id,qty:1}]).total;
const cartCount=()=>state.cart.reduce((n,i)=>n+i.qty,0);
const logo=()=>`<a href="#home" class="logo" aria-label="DutyFreeDeal home"><img class="logo-mark" src="./assets/favicon.svg" alt=""><span class="logo-word">DutyFree<span class="gold">Deal</span><small>.com</small></span></a>`;
function header(){return `<div class="topbar"><div class="container"><span>A world of exceptional finds. One transparent delivered price.</span><span class="demo">INTERACTIVE PROTOTYPE</span><a href="#apply">Become a founding vendor</a></div></div><header><div class="header container">${logo()}<form class="search-box" id="search-form" role="search"><input name="search" aria-label="Search products, brands or countries" placeholder="Search products, brands or countries…" value="${esc(state.search)}"><button aria-label="Search">${icon('search')}</button></form><div class="header-actions"><label class="destination">${icon('globe')}<span><small>Deliver to</small><select id="destination" aria-label="Delivery country">${Object.entries(countries).map(([code,c])=>`<option value="${code}" ${code===state.destination?'selected':''}>${c.name}</option>`).join('')}</select></span></label><a class="icon-link" href="#account">${icon('user')}<span class="action-label">Account</span></a><a class="icon-link" href="#cart" aria-label="Shopping bag, ${cartCount()} items">${icon('bag')}<span class="cart-count">${cartCount()}</span><span class="action-label">Bag</span></a></div></div><nav class="navigation" aria-label="Main navigation"><div class="container nav-inner"><a class="all-cats" href="#shop">${icon('menu',true)}All categories</a><a href="#shop/Fashion">Fashion</a><a href="#shop/Beauty">Beauty</a><a href="#shop/Electronics">Electronics</a><a href="#shop/Watches%20%26%20Jewelry">Watches & Jewelry</a><a href="#shop/Home%20%26%20Living">Home & Living</a><a href="#shop/Travel">Travel</a><a class="right" href="#how">How it works</a></div></nav></header>`;}
