function card(p){return `<article class="product-card"><a class="product-image" href="#product/${p.id}"><span class="product-badge">${money(p.discount).replace('.00','')} duty offset</span><img src="${photoSrc(p)}" alt="${esc(p.name)}" loading="lazy"></a><button class="heart ${state.wishlist.includes(p.id)?'active':''}" data-action="wish" data-id="${p.id}" aria-label="${state.wishlist.includes(p.id)?'Remove from':'Add to'} wishlist" aria-pressed="${state.wishlist.includes(p.id)}">${icon('heart',true)}</button><div class="product-info"><div class="product-origin"><span class="flag">${p.flag}</span>Ships from ${esc(p.country)}</div><a href="#product/${p.id}" class="product-name">${esc(p.name)}</a><div class="product-sub">${esc(p.brand)}</div><div class="product-rating"><span class="stars" aria-label="${p.rating} stars">★★★★★</span><span>${p.rating} (${p.reviews})</span></div><div class="product-prices"><strong>${money(net(p))}</strong><del>${money(p.price)}</del></div><div class="product-delivered">${icon('check',true)}Est. delivered <b>${money(delivered(p))}</b></div><div class="product-actions"><button class="btn secondary" data-action="add" data-id="${p.id}" ${p.stock<1?'disabled':''}>${icon('bag',true)}Add to bag</button></div></div></article>`;}
function howContent(){return `<div class="how-grid"><div class="how-item"><span class="step-number">01</span><div><h3>Discover something different</h3><p>Explore considered products from independent vendors around the world.</p></div></div><div class="how-item"><span class="step-number">02</span><div><h3>See the whole price</h3><p>Product, vendor discount, shipping and estimated duties & taxes. All in one place.</p></div></div><div class="how-item"><span class="step-number">03</span><div><h3>One checkout. To your door.</h3><p>Shop across vendors in a single order. Track each shipment along the way.</p></div></div></div>`;}
function home(){const example=estimate([{id:'watch',qty:1}]);return `<main id="main"><section class="hero"><div class="container hero-inner"><div class="hero-copy"><div class="eyebrow">The world, within reach</div><h1>Shop the world.<br>Know your<br><span>delivered price.</span></h1><p>Discover exceptional products from global vendors. Shipping, duties and taxes, made clear before you check out.</p><div class="hero-buttons"><a class="btn primary" href="#shop">Explore the marketplace</a><a class="btn secondary" href="#apply">Become a vendor</a></div><div class="hero-note">${icon('shield')}A little more discovery. A lot fewer surprises.</div></div><div class="hero-visual"><img src="./assets/hero.jpg" alt="A considered collection of travel, fashion and lifestyle essentials"><div class="hero-stamp">${icon('globe',true)}Great finds. Without borders.</div><div class="price-float"><div class="overline">THE PRICE, MADE CLEAR</div><h4>${products[3].name}</h4><div class="price-row"><span>Product price</span><strong>${money(495)}</strong></div><div class="price-row discount"><span>Vendor duty offset</span><strong>−${money(55)}</strong></div><div class="price-row"><span>Shipping</span><strong>${money(example.shipping)}</strong></div><div class="price-row"><span>Est. duties & taxes</span><strong>${money(example.duty+example.tax)}</strong></div><div class="price-row total"><span>Est. delivered</span><strong>${money(example.total)}</strong></div><div class="micro">To ${countries[state.destination].name} · illustrative estimate</div></div></div></div></section><div class="trust-strip"><div class="container trust-grid">${[['globe','A truly global selection','Independent vendors. Exceptional finds.'],['tag','Vendor duty offsets','Thoughtful savings across borders.'],['box','Transparent delivered pricing','See the estimate before you pay.'],['shield','One secure checkout','Multiple vendors. One simple order.']].map(([i,t,s])=>`<div class="trust-item">${icon(i)}<div><strong>${t}</strong><span>${s}</span></div></div>`).join('')}</div></div><section class="section container"><div class="section-head"><div><h2>A world of possibilities.</h2><p>Find your next favorite, wherever it comes from.</p></div><a class="text-link" href="#shop">Explore all categories</a></div><div class="category-grid">${categories.map(c=>`<a class="category-card" href="#shop/${encodeURIComponent(c.name)}"><div class="category-image"><img src="./assets/${c.image}" alt="${c.label}" loading="lazy"></div><h3>${c.label}</h3><p>${c.sub}</p></a>`).join('')}</div></section><section class="section container" style="padding-top:8px"><div class="section-head"><div><div class="eyebrow" style="margin-bottom:10px">Curated across continents</div><h2>Good finds. Great arrivals.</h2></div><a class="text-link" href="#shop">Shop all discoveries</a></div><div class="product-grid">${products.slice(0,4).map(card).join('')}</div></section><section class="section tinted" id="how-section"><div class="container"><div class="section-head"><div><h2>Across borders. Without the guesswork.</h2><p>A simpler way to bring the world home.</p></div></div>${howContent()}</div></section><section class="section container"><div class="vendor-banner"><div><div class="eyebrow">Founding vendor program</div><h2>Your next customer could be anywhere.</h2><p>Join a marketplace built for global discovery. Apply to become one of our founding vendors and take your business beyond borders.</p></div><a class="btn gold" href="#apply">Apply as a vendor</a></div></section></main>`;}
