function catalog(){const selected=state.category;let found=products.filter(p=>(selected==='All'||p.category===selected)&&(state.origin==='All'||p.country===state.origin)&&net(p)<=state.maxPrice&&(`${esc(p.name)} ${esc(p.brand)} ${esc(p.country)} ${p.category}`.toLowerCase().includes(state.search.toLowerCase())));if(state.sort==='price-low')found.sort((a,b)=>net(a)-net(b));if(state.sort==='price-high')found.sort((a,b)=>net(b)-net(a));if(state.sort==='rating')found.sort((a,b)=>b.rating-a.rating);return `<main id="main" class="container">${crumbs([['Shop',null],...(selected==='All'?[]:[[selected,null]])])}<div class="catalog"><details class="filters" ${window.innerWidth>760?'open':''}><summary class="filter-summary">${icon('filter',true)}Filter products</summary><div class="filters-content"><div class="filter-group"><h3>Categories</h3><div class="filter-options">${['All',...categories.map(c=>c.name)].map(c=>`<button data-action="filter-category" data-value="${esc(c)}" class="${selected===c?'active':''}">${c==='All'?'All products':esc(c)}<span>${products.filter(p=>c==='All'||p.category===c).length}</span></button>`).join('')}</div></div><div class="filter-group"><h3>Ships from</h3><div class="filter-options">${['All',...new Set(products.map(p=>p.country))].map(c=>`<label><input type="radio" name="origin" value="${esc(c)}" ${state.origin===c?'checked':''}>${c==='All'?'Anywhere in the world':esc(c)}</label>`).join('')}</div></div><div class="filter-group"><h3>Price after vendor discount</h3><input class="range" id="price-range" aria-label="Maximum product price" type="range" min="100" max="${priceCap()}" step="25" value="${Number.isFinite(state.maxPrice)?state.maxPrice:priceCap()}"><div class="range-labels"><span>$0</span><span>${Number.isFinite(state.maxPrice)?'Up to '+money(state.maxPrice).replace('.00',''):'All prices'}</span></div></div><button class="text-link filter-reset" data-action="reset-filters">Clear all filters</button></div></details><div><div class="catalog-head"><div><h1>${state.search?`Results for “${esc(state.search)}”`:selected==='All'?'Discover the world.':esc(selected)}</h1><p>${found.length} ${found.length===1?'discovery':'discoveries'} · Delivered estimates to ${countries[state.destination].name}</p></div><select id="sort" aria-label="Sort products"><option value="featured" ${state.sort==='featured'?'selected':''}>Featured</option><option value="price-low" ${state.sort==='price-low'?'selected':''}>Price: low to high</option><option value="price-high" ${state.sort==='price-high'?'selected':''}>Price: high to low</option><option value="rating" ${state.sort==='rating'?'selected':''}>Top rated</option></select></div><div class="product-grid">${found.length?found.map(card).join(''):`<div class="empty-state">${icon('search')}<h2>No discoveries just yet.</h2><p>Try another search or clear your filters to explore the full selection.</p><button class="btn primary" data-action="reset-filters">Show all products</button></div>`}</div></div></div></main>`;}
function detail(id){const p=product(id);if(!p)return notFound();const t=estimate([{id,qty:1}]);return `<main id="main" class="container">${crumbs([['Shop','#shop'],[p.category,`#shop/${encodeURIComponent(p.category)}`],[p.name,null]])}<div class="product-detail"><div><div class="detail-photo"><img src="${photoSrc(p)}" alt="${esc(p.name)}"><button class="heart ${state.wishlist.includes(id)?'active':''}" data-action="wish" data-id="${id}" aria-label="Save to wishlist" aria-pressed="${state.wishlist.includes(id)}">${icon('heart')}</button></div><div class="photo-caption">A global find. A clearly delivered price.</div></div><div class="detail-body"><div class="detail-brand">${esc(p.brand)}</div><h1>${esc(p.name)}</h1><div class="product-rating"><span class="stars">★★★★★</span><span>${p.rating} · ${p.reviews} demo reviews</span></div><div class="product-origin"><span class="flag">${p.flag}</span>Ships from ${esc(p.country)} <span style="margin-left:auto" class="stock">${icon('check',true)}${p.stock>0?'In stock':'Out of stock'}</span></div><p class="detail-description">${esc(p.desc)}</p><div class="detail-price">${money(net(p))}<del>${money(p.price)}</del></div><p class="discount-note">${money(p.discount)} vendor duty offset included</p><div class="variant"><label>Selected finish</label><span class="variant-chip">${esc(p.color)}</span></div><div class="buy-row"><div class="quantity"><button data-action="detail-qty" data-delta="-1" aria-label="Decrease quantity">${icon('minus',true)}</button><input type="number" id="detail-quantity" min="1" max="10" value="1" aria-label="Product quantity"><button data-action="detail-qty" data-delta="1" aria-label="Increase quantity">${icon('plus',true)}</button></div><button class="btn primary" data-action="detail-add" data-id="${id}" ${p.stock<1?'disabled':''}>${icon('bag',true)}Add to bag</button></div><div class="estimate-card"><h3>${icon('globe',true)}Your delivered price · ${countries[state.destination].flag} ${countries[state.destination].name}</h3>${estimateRows(t)}<p>Illustrative estimate for 1 item. Shipping and import charges are simulated and will be reviewed in your bag. A vendor duty offset is a discount; duties may still apply.</p></div><div class="detail-perks"><div>${icon('truck')}<span><strong>Worldwide delivery</strong>5–9 business days · demo estimate</span></div><div>${icon('shield')}<span><strong>Shop with confidence</strong>Return and support flow available</span></div></div></div></div><details class="detail-tabs" open><summary>Product & shipping details</summary><dl class="spec-grid">${[['Vendor',p.vendor],['SKU',p.sku],['Shipping weight',`${p.weight} kg`],['Package dimensions',p.dimensions],['Available inventory',`${p.stock} units`],['Ships from',p.country],['Category',p.category],['Offer information','Demonstration data']].map(([k,v])=>`<div><dt>${k}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl></details><section class="section" style="padding-top:15px"><div class="section-head"><div><h2>A little more to discover.</h2></div><a class="text-link" href="#shop">Explore the marketplace</a></div><div class="product-grid">${products.filter(x=>x.id!==id).slice(0,4).map(card).join('')}</div></section></main>`;}
function shippingGroups(t){return t.shipments.map((s,i)=>`<div class="shipping-group"><div><h4>${icon('box',true)}Shipment ${i+1} · ${s.vendor}</h4><p>${s.items[0].flag} From ${s.items[0].country} · ${s.items.reduce((n,p)=>n+p.qty,0)} item(s) · ${state.delivery==='express'?'5–9':'9–14'} business days</p></div><span>${money(s.shipping)}</span></div>`).join('');}
function summary(t,checkout=false){return `<aside class="summary"><h2>Order summary</h2><label class="destination"><small>Delivery destination</small><select id="summary-destination" aria-label="Delivery country">${Object.entries(countries).map(([code,c])=>`<option value="${code}" ${state.destination===code?'selected':''}>${c.flag} ${c.name}</option>`).join('')}</select></label>${estimateRows(t)}${checkout?'':`<a class="btn primary full" href="#checkout">${icon('lock',true)}Continue to checkout</a>`}<p class="summary-note">${icon('info')}Demo estimate. Carrier rates and customs calculations are simulated. No payment is collected.</p><hr><p class="summary-note">${icon('shield')}One checkout. ${t.shipments.length} ${t.shipments.length===1?'vendor':'vendors'}. Each shipment tracked separately.</p></aside>`;}
function cart(){if(!state.cart.length)return `<main id="main" class="container">${crumbs([['Shopping bag',null]])}<div class="empty-state" style="margin-bottom:55px">${icon('bag')}<h2>Your next discovery is out there.</h2><p>Your bag is empty. Explore products from vendors around the world.</p><a class="btn primary" href="#shop">Explore the marketplace</a></div></main>`;const t=estimate(state.cart);return `<main id="main" class="container">${crumbs([['Shopping bag',null]])}<div class="section-head" style="margin-bottom:5px"><div><h1 class="page-title">Your shopping bag <span style="font-size:19px;color:var(--muted);font-weight:450">(${cartCount()})</span></h1><p>Global discoveries. One simple checkout.</p></div><a class="text-link" href="#shop">Continue discovering</a></div><div class="cart-layout"><div><div class="cart-items">${state.cart.map(i=>{const p=product(i.id);return `<article class="cart-item"><a href="#product/${p.id}"><img src="${photoSrc(p)}" alt="${esc(p.name)}"></a><div><a href="#product/${p.id}"><h3>${esc(p.name)}</h3></a><p class="product-sub">${esc(p.brand)} · ${esc(p.color)}</p><div class="product-origin">${p.flag} ${esc(p.country)} · ${esc(p.vendor)}</div><div class="item-controls"><div class="quantity"><button data-action="cart-qty" data-id="${p.id}" data-delta="-1" aria-label="Decrease ${esc(p.name)} quantity" ${i.qty===1?'disabled':''}>${icon('minus',true)}</button><span>${i.qty}</span><button data-action="cart-qty" data-id="${p.id}" data-delta="1" aria-label="Increase ${esc(p.name)} quantity" ${i.qty>=10?'disabled':''}>${icon('plus',true)}</button></div><button class="remove" data-action="remove" data-id="${p.id}">Remove</button></div></div><div class="cart-price"><strong>${money(net(p)*i.qty)}</strong><del>${money(p.price*i.qty)}</del><p class="discount-note">−${money(p.discount*i.qty)} duty offset</p></div></article>`;}).join('')}</div><h3 class="shipment-heading">Your order, split by vendor.</h3><p class="page-subtitle" style="font-size:12px;margin-top:7px">Each seller dispatches their own parcel. Shipping is estimated per shipment.</p>${shippingGroups(t)}<div class="shipping-options"><label class="shipping-option"><input type="radio" name="delivery" value="express" ${state.delivery==='express'?'checked':''}><span>DHL Express · demo<small>5–9 business days</small></span><strong>${money(estimate(state.cart,'express').shipping)}</strong></label><label class="shipping-option"><input type="radio" name="delivery" value="economy" ${state.delivery==='economy'?'checked':''}><span>International economy · demo<small>9–14 business days</small></span><strong>${money(estimate(state.cart,'economy').shipping)}</strong></label></div></div>${summary(t)}</div></main>`;}
function checkout(){if(!state.cart.length)return cart();const t=estimate(state.cart);return `<main id="main" class="container">${crumbs([['Shopping bag','#cart'],['Checkout',null]])}<h1 class="page-title">A world of finds, on its way.</h1><div class="cart-layout"><form id="checkout-form"><div class="checkout-steps"><span class="current">01 · Delivery details</span>${icon('chevron',true)}<span>02 · Demo confirmation</span></div><div class="demo-note">${icon('info')}This is a prototype checkout. Use sample information to explore the experience. No payment or real order will be processed.</div><section class="form-panel"><h2>Where should we send it?</h2><div class="form-grid"><div class="field"><label for="firstName">First name</label><input id="firstName" name="firstName" autocomplete="given-name" required placeholder="Alex" maxlength="60"></div><div class="field"><label for="lastName">Last name</label><input id="lastName" name="lastName" autocomplete="family-name" required placeholder="Morgan" maxlength="60"></div><div class="field full"><label for="email">Email address</label><input type="email" id="email" name="email" autocomplete="email" required placeholder="alex@example.com"></div><div class="field full"><label for="address">Street address</label><input id="address" name="address" autocomplete="street-address" required placeholder="123 Discovery Avenue" maxlength="150"></div><div class="field"><label for="city">City</label><input id="city" name="city" autocomplete="address-level2" required placeholder="Your city" maxlength="80"></div><div class="field"><label for="postal">Postal code</label><input id="postal" name="postal" autocomplete="postal-code" required placeholder="Postal code" maxlength="20"></div><div class="field full"><label>Country</label><input value="${countries[state.destination].name}" readonly aria-label="Destination country"><small>Change the destination in the order summary.</small></div></div></section><section class="form-panel"><h2>Your shipments</h2>${shippingGroups(t)}<p class="page-subtitle" style="font-size:12px;margin-top:16px">${state.delivery==='express'?'DHL Express':'International economy'} · tracking provided separately for each vendor.</p></section><button class="btn primary full" type="submit">${icon('check',true)}Place demo order · ${money(t.total)}</button><p class="summary-note">${icon('lock')}No card details required. This action only creates an order within this demo session.</p></form>${summary(t,true)}</div></main>`;}
function confirmation(){const o=state.order;if(!o)return notFound();return `<main id="main" class="container"><div class="success-page"><div class="success-icon">${icon('check')}</div><div class="eyebrow" style="margin-bottom:13px">Demo order confirmed</div><h1>A little piece of the world.<br>Coming your way, ${esc(o.name)}.</h1><p class="page-subtitle">You have completed the prototype checkout. Explore how your shipments would appear below.</p><div class="success-details"><div><small>Order number</small><strong>${o.id}</strong></div><div><small>Est. delivered total</small><strong>${money(o.total)}</strong></div><div><small>Delivery destination</small><strong>${o.country}</strong></div><div><small>Status</small>${chip('Processing')}</div></div>${o.shipments.map((s,i)=>`<div class="form-panel"><div class="panel-head"><h2 style="margin-bottom:0">Shipment ${i+1} · ${s.vendor}</h2>${chip('Awaiting shipment')}</div>${s.items.map(p=>`<div class="order-line"><span>${esc(p.name)} × ${p.qty}</span><strong>${money(net(p)*p.qty)}</strong></div>`).join('')}<p class="page-subtitle" style="font-size:12px;margin-top:15px">Demo tracking: DFD-${i+1}-DEMO · ${o.service==='express'?'5–9':'9–14'} business days</p></div>`).join('')}<div class="demo-note">${icon('info')}No order has been sent to a vendor and no payment has been collected. Information stays in this temporary demonstration.</div><div class="hero-buttons"><a class="btn primary" href="#shop">Keep discovering</a><a class="btn secondary" href="#account">View demo orders</a></div></div></main>`;}
function apply(){if(state.submitted)return `<main id="main" class="container"><div class="success-page"><div class="success-icon">${icon('check')}</div><h1>Welcome to a world of opportunity.</h1><p class="page-subtitle">Your demo application for ${esc(state.application.business)} is ready for review. Open the admin dashboard to approve it, or explore the vendor portal.</p><div class="form-panel"><div class="order-line"><span>Business</span><strong>${esc(state.application.business)}</strong></div><div class="order-line"><span>Country</span><strong>${esc(state.application.country)}</strong></div><div class="order-line"><span>Status</span>${chip(state.vendorStatus['new-vendor']||'Pending review')}</div></div><div class="demo-note">${icon('info')}Demo application only. No application or email has been sent.</div><div class="hero-buttons"><a class="btn primary" href="#seller">Explore vendor portal</a><a class="btn secondary" href="#admin">Review in admin</a></div></div></main>`;return `<main id="main" class="onboarding"><div class="container apply-layout"><div class="apply-copy"><div class="eyebrow">Founding vendor program</div><h1>Your world.<br><span>A bigger audience.</span></h1><p>Bring your products to a global marketplace built around discovery, clear pricing and a simpler international shopping experience.</p><div class="apply-benefits">${[['globe','Connect beyond borders','Reach customers in new markets from one vendor workspace.'],['box','Your products. Your control.','Manage listings, stock, orders and shipping details in one place.'],['wallet','Clear commissions & payouts','Track your sales, platform fees and payout status.']].map(([i,t,p])=>`<div>${icon(i)}<span><strong>${t}</strong><p>${p}</p></span></div>`).join('')}</div><p class="founder-number">Our first chapter: onboarding 2,000–3,000 founding vendors before public launch.</p></div><div class="apply-card"><h2>Let’s meet your business.</h2><p>Tell us a little about what you make or sell.</p><form id="apply-form" class="apply-form form-grid"><div class="field full"><label for="business">Business name</label><input id="business" name="business" required placeholder="Your company or store" maxlength="100"></div><div class="field"><label for="contact">Contact name</label><input id="contact" name="contact" required placeholder="First and last name" maxlength="100"></div><div class="field"><label for="vendor-email">Business email</label><input id="vendor-email" name="email" type="email" required placeholder="you@company.com"></div><div class="field"><label for="vendor-country">Business country</label><select name="country" id="vendor-country" required><option value="">Choose a country</option>${['United States','France','United Kingdom','Italy','Japan','Germany','Switzerland','Portugal','Denmark','South Korea','China','United Arab Emirates','Canada','Other'].map(c=>`<option>${c}</option>`).join('')}</select></div><div class="field"><label for="vendor-category">Main product category</label><select id="vendor-category" name="category" required><option value="">Choose a category</option>${categories.map(c=>`<option>${c.name}</option>`).join('')}</select></div><div class="field full"><label for="vendor-catalog">Approximate catalog size</label><select id="vendor-catalog" name="size"><option>1–50 products</option><option>51–500 products</option><option>501–5,000 products</option><option>5,000+ products</option></select></div><div class="field full"><label for="vendor-about">Tell us about your products</label><textarea id="vendor-about" name="about" required placeholder="What makes your selection special?" maxlength="1500"></textarea></div><label class="checkbox-line"><input type="checkbox" required>I understand this is a demo application. I am using sample information to preview vendor onboarding.</label><button class="btn primary field full" type="submit">Submit demo application</button><small style="grid-column:1/-1;text-align:center;font-size:12px;color:var(--muted)">Demo only · No account is created and no information is sent.</small></form></div></div></main>`;}
const metrics=entries=>`<div class="metric-grid">${entries.map(([label,value,note,i,neutral])=>`<div class="metric"><span>${label}</span>${icon(i||'chart')}<strong>${value}</strong><small class="${neutral?'neutral':''}">${note}</small></div>`).join('')}</div>`;
const revenueChart=()=>`<div class="chart" role="img" aria-label="Demo monthly revenue: May 2,300 dollars, June 3,400, July 3,100, August 4,850, September 4,300, October 5,290">${[['May',40],['Jun',57],['Jul',53],['Aug',79],['Sep',72],['Oct',91]].map(([month,height])=>`<div class="chart-bar" style="--height:${height}%" title="${month} demo revenue"><span>${month}</span></div>`).join('')}</div><div class="chart-legend"><span>Revenue after vendor discounts · sample data</span><strong>$23,240.00</strong></div>`;
function ordersTable(orders,admin=false){return `<div class="table-wrap"><table class="data-table"><thead><tr><th>Order</th><th>Customer</th><th>Destination</th><th>Total</th><th>Status</th><th></th></tr></thead><tbody>${orders.map(o=>`<tr><td><strong>${o.id}</strong><br><small style="font-size:12px;color:var(--muted)">${o.date}</small></td><td>${esc(o.customer)}</td><td>${o.country}</td><td>${money(o.total)}</td><td>${chip(o.status)}</td><td><button class="table-action" data-action="order-detail" data-id="${o.id}">View order</button></td></tr>`).join('')}</tbody></table></div>`;}
function dashboardShell(admin=false){const current=admin?state.adminTab:state.dashboard;const tabs=admin?[['overview','grid','Overview'],['vendors','globe','Vendors'],['products','box','Products'],['orders','bag','Orders & disputes'],['payments','wallet','Payments'],['settings','settings','Commissions']]:[['overview','grid','Overview'],['products','box','Products'],['orders','bag','Orders'],['payments','wallet','Payouts']];return `<main id="main" class="dashboard-shell"><aside class="dashboard-side"><span class="workspace-label">${admin?'MARKETPLACE ADMIN':'VENDOR WORKSPACE'}</span><div class="workspace-user"><div class="avatar">${admin?'DF':'TS'}</div><div><strong>${admin?'DutyFreeDeal':state.application&&state.vendorStatus['new-vendor']==='Approved'?esc(state.application.business):'Tokyo Sound Co.'}</strong><small>${admin?'Marketplace administrator':state.application&&state.vendorStatus['new-vendor']==='Approved'?esc(state.application.country)+' · Demo vendor':'🇯🇵 Tokyo, Japan · Demo vendor'}</small></div></div><nav class="side-nav" aria-label="${admin?'Admin':'Vendor'} sections">${tabs.map(([id,i,label])=>`<button data-action="dashboard-tab" data-admin="${admin}" data-value="${id}" class="${current===id?'active':''}">${icon(i)}${label}</button>`).join('')}</nav><div class="side-note"><strong>${admin?'Build supply before launch.':'A world of opportunity.'}</strong>${admin?'Monitor founding vendor onboarding and review new applications.':'Your products are ready for a global audience. Keep inventory and shipping data up to date.'}<a href="${admin?'#seller':'#admin'}">${admin?'Explore vendor portal':'Explore admin dashboard'}</a><a href="#home">Back to the marketplace</a></div></aside><div class="dashboard-main">${admin?adminContent():sellerContent()}</div></main>`;}
function sellerContent(){const tab=state.dashboard;const heading=`<div class="dashboard-heading"><div><h1>${{overview:'Good morning, Tokyo Sound.',products:'Your products.',orders:'Your orders.',payments:'Your payouts.'}[tab]}</h1><p>${{overview:'Your business, beyond borders. Here’s how things are looking.',products:'Manage your selection, shipping data and available inventory.',orders:'Track international orders and manage each shipment.',payments:'A clear view of earnings, commissions and payouts.'}[tab]}</p></div>${tab==='products'?'<button class="btn primary small" data-action="new-product">'+icon('plus',true)+'Add a product</button>':'<span>October 2026 · Demo data</span>'}</div>`;const allOrders=[...state.orders,...demoOrders];if(tab==='overview')return heading+metrics([['Total revenue','$23,240.00','+18.6% vs. previous month','chart'],['Orders','68','+12 orders this month','bag'],['Active products',String(2+state.extraProducts.filter(p=>state.productStatus[p.id]==='Approved').length),'2 ready for international shipping','box',true],['Available balance','$4,860.40','Next payout: October 9','wallet',true]])+`<div class="dashboard-row"><section class="panel"><div class="panel-head"><h2>Sales at a glance</h2><small>Last 6 months</small></div>${revenueChart()}</section><section class="panel"><div class="panel-head"><h2>Your latest activity</h2></div><div class="activity"><div class="activity-item">${icon('bag')}<span><strong>New order from the UK</strong><small>DFD-1048 · Studio audio · 18 minutes ago</small></span></div><div class="activity-item">${icon('check')}<span><strong>Order delivered in France</strong><small>DFD-1047 · Customer notified · 2 hours ago</small></span></div><div class="activity-item">${icon('wallet')}<span><strong>Your payout is scheduled</strong><small>$4,860.40 · October 9, 2026</small></span></div></div></section></div><section class="panel"><div class="panel-head"><h2>Recent orders</h2><button class="text-link" data-action="dashboard-tab" data-admin="false" data-value="orders">View all orders</button></div>${ordersTable(allOrders.slice(0,4))}</section>`;
if(tab==='products'){const listing=[...products.filter(p=>p.vendor==='Tokyo Sound Co.'&&!p.custom),...state.extraProducts];const filtered=listing.filter(p=>p.name.toLowerCase().includes(state.tableSearch.toLowerCase())&&(state.tableStatus==='All'||(state.productStatus[p.id]|| (p.custom?'Pending review':'Live'))===state.tableStatus));return heading+`<div class="table-toolbar"><input id="table-search" type="search" aria-label="Search vendor products" placeholder="Search your products…" value="${esc(state.tableSearch)}"><select id="table-status" aria-label="Filter product status">${['All','Live','Pending review','Approved','Rejected'].map(s=>`<option ${s===state.tableStatus?'selected':''}>${s}</option>`).join('')}</select><span>${filtered.length} products</span></div><section class="panel"><div class="table-wrap"><table class="data-table"><thead><tr><th>Product</th><th>SKU</th><th>Price</th><th>Stock</th><th>Status</th><th></th></tr></thead><tbody>${filtered.map(p=>`<tr><td><div class="table-product"><img src="${p.custom?(p.photo||'./assets/favicon.svg'):'./assets/'+p.image}" alt=""><span><strong>${esc(p.name)}</strong><small>${esc(p.category)}</small></span></div></td><td>${esc(p.sku)}</td><td>${money(p.price)}</td><td>${p.stock}</td><td>${chip(state.productStatus[p.id]||(p.custom?'Pending review':'Live'))}</td><td><button class="table-action" data-action="edit-stock" data-id="${p.id}">Edit stock</button></td></tr>`).join('')||'<tr><td colspan="6">No products match your search.</td></tr>'}</tbody></table></div></section><div class="demo-note" style="margin-top:20px">${icon('info')}New products enter the review queue. Open the admin dashboard to approve them. Uploaded images stay in this demo session.</div>`;}
if(tab==='orders')return heading+`<section class="panel">${ordersTable(allOrders)}</section><div class="demo-note" style="margin-top:22px">${icon('info')}Open an order to explore shipment tracking, support and the refund flow. All actions are simulated.</div>`;
return heading+`<section class="panel balance-panel"><div><small>Available for payout</small><h2>${state.payoutRequested?'$0.00':'$4,860.40'}</h2><p>Platform commission: ${state.commissions}% · Amounts are demonstration data</p></div><button class="btn gold" data-action="request-payout" ${state.payoutRequested?'disabled':''}>${state.payoutRequested?'Demo payout scheduled':'Request demo payout'}</button></section>`+metrics([['Total earnings','$20,451.20','After platform commission','wallet',true],['Platform fees','$2,788.80','Illustrative commission history','tag',true],['Last payout','$3,120.00','October 2, 2026','check',true],['Next scheduled payout',state.payoutRequested?'Pending':'Oct 9','Weekly payout schedule','wallet',true]])+`<section class="panel"><div class="panel-head"><h2>Payout history</h2><small>Demo transactions</small></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Reference</th><th>Date</th><th>Amount</th><th>Destination</th><th>Status</th></tr></thead><tbody>${state.payoutRequested?'<tr><td>PO-DEMO-NEW</td><td>October 6, 2026</td><td>$4,860.40</td><td>Demo bank ···· 4281</td><td>'+chip('Pending')+'</td></tr>':''}<tr><td>PO-2026-1002</td><td>October 2, 2026</td><td>$3,120.00</td><td>Demo bank ···· 4281</td><td>${chip('Paid')}</td></tr><tr><td>PO-2026-0925</td><td>September 25, 2026</td><td>$2,640.00</td><td>Demo bank ···· 4281</td><td>${chip('Paid')}</td></tr></tbody></table></div></section>`;
}
const vendors=[{id:'v1',name:'Tokyo Sound Co.',country:'🇯🇵 Japan',category:'Electronics',products:248,sales:23240,status:'Active'},{id:'v2',name:'Maison Aurelle',country:'🇫🇷 France',category:'Beauty',products:76,sales:18450,status:'Active'},{id:'v3',name:'Atelier Milano',country:'🇮🇹 Italy',category:'Fashion',products:124,sales:0,status:'Pending review'},{id:'v4',name:'Nordic Objects',country:'🇩🇰 Denmark',category:'Home & Living',products:38,sales:0,status:'Pending review'},{id:'v5',name:'Nomad Goods',country:'🇩🇪 Germany',category:'Travel',products:59,sales:12490,status:'Active'}];
function adminContent(){const tab=state.adminTab;const headings={overview:['The world is coming together.','Build the supply side. Approve vendors, review products and monitor the marketplace.'],vendors:['Your global vendor network.','Review applications and onboard your founding vendors.'],products:['A considered global catalog.','Review listings and international shipping information.'],orders:['Orders & customer care.','Monitor split orders, shipment tracking and customer requests.'],payments:['Marketplace payments.','Oversee collected payments, vendor commissions and payout status.'],settings:['A clear commission structure.','Set the default marketplace fee used by the vendor payout demonstration.']};const heading=`<div class="dashboard-heading"><div><h1>${headings[tab][0]}</h1><p>${headings[tab][1]}</p></div><span>Marketplace overview · Demo data</span></div>`;const onboarded=1248+Object.values(state.vendorStatus).filter(s=>s==='Approved').length;const pending=vendors.filter(v=>(state.vendorStatus[v.id]||v.status)==='Pending review').length+(state.application&&!state.vendorStatus['new-vendor']?1:0);const allVendors=state.application?[...vendors,{id:'new-vendor',name:state.application.business,country:state.application.country,category:state.application.category,products:0,sales:0,status:'Pending review'}]:vendors;
if(tab==='overview')return heading+metrics([['Onboarded vendors',String(onboarded),'Across 42 countries','globe',true],['Live products','86,420','+2,840 this month','box'],['Gross sales','$284,650','+24.3% vs. previous month','chart'],['Awaiting review',String(pending+state.extraProducts.filter(p=>!state.productStatus[p.id]).length),'Vendor and product applications','shield',true]])+`<section class="growth-goal"><div><h3>Founding vendor program</h3><p>Supply first. Build toward 3,000 vendors before public launch.</p></div><div><div class="progress-label"><strong>${onboarded.toLocaleString()} onboarded</strong><span>3,000 vendor target</span></div><div class="progress-track"><span style="width:${(onboarded/3000*100).toFixed(1)}%"></span></div></div></section><div class="dashboard-row"><section class="panel"><div class="panel-head"><h2>Marketplace performance</h2><small>Demonstration figures</small></div>${revenueChart()}</section><section class="panel"><div class="panel-head"><h2>Top destination countries</h2></div><div class="country-sales">${[['🇺🇸 United States','$98,400',83],['🇬🇧 United Kingdom','$62,850',61],['🇫🇷 France','$48,320',45],['🇦🇪 United Arab Emirates','$31,760',31]].map(([c,n,w])=>`<div class="country-sale"><span>${c}</span><small>${n}</small><div class="progress-track"><span style="width:${w}%"></span></div></div>`).join('')}</div></section></div><section class="panel"><div class="panel-head"><h2>Vendor applications</h2><button class="text-link" data-action="dashboard-tab" data-admin="true" data-value="vendors">Manage vendors</button></div>${vendorTable(allVendors.filter(v=>(state.vendorStatus[v.id]||v.status)==='Pending review'))}</section>`;
if(tab==='vendors')return heading+`<div class="table-toolbar"><input id="table-search" type="search" aria-label="Search vendors" placeholder="Search vendor names…" value="${esc(state.tableSearch)}"><select id="table-status" aria-label="Filter vendors by status">${['All','Active','Pending review','Approved','Rejected'].map(s=>`<option ${s===state.tableStatus?'selected':''}>${s}</option>`).join('')}</select><span>${allVendors.length} sample vendors</span></div><section class="panel">${vendorTable(allVendors.filter(v=>v.name.toLowerCase().includes(state.tableSearch.toLowerCase())&&(state.tableStatus==='All'||(state.vendorStatus[v.id]||v.status)===state.tableStatus)))}</section>`;
if(tab==='products'){const pendingProducts=[...state.extraProducts,...products.filter(p=>!p.custom)];return heading+`<section class="panel"><div class="panel-head"><h2>Product review queue</h2><small>${state.extraProducts.length} vendor-submitted product(s)</small></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Product</th><th>Vendor</th><th>Shipping data</th><th>Status</th><th>Review</th></tr></thead><tbody>${pendingProducts.map(p=>`<tr><td><div class="table-product"><img src="${p.custom?(p.photo||'./assets/favicon.svg'):'./assets/'+p.image}" alt=""><span><strong>${esc(p.name)}</strong><small>${esc(p.sku)} · ${money(p.price)}</small></span></div></td><td>${esc(p.vendor||'Tokyo Sound Co.')}</td><td>${p.weight} kg<br><small style="font-size:12px;color:var(--muted)">${esc(p.dimensions)}</small></td><td>${chip(state.productStatus[p.id]||(p.custom?'Pending review':'Approved'))}</td><td>${p.custom&&!state.productStatus[p.id]?`<button class="table-action" data-action="review-product" data-id="${p.id}">Review listing</button>`:'<span style="color:var(--muted);font-size:12px">Reviewed</span>'}</td></tr>`).join('')}</tbody></table></div></section>`;}
if(tab==='orders')return heading+`<section class="panel"><div class="panel-head"><h2>Marketplace orders</h2><small>Split fulfillment · demo</small></div>${ordersTable([...state.orders,...demoOrders],true)}</section>`;
if(tab==='settings')return heading+`<section class="panel settings-form"><h2 style="margin-bottom:23px">Default vendor commission</h2><form id="commission-form"><div class="field"><label for="commission">Commission rate (%)</label><input id="commission" name="commission" type="number" value="${state.commissions}" min="0" max="50" step=".5" required><small>Applied to the product price after vendor discounts. Shipping and estimated import charges are excluded in this demo.</small></div><div class="estimate-card" style="margin-top:20px"><h3>Example · a $100 product sale</h3><div class="price-row"><span>Platform commission</span><strong>${money(state.commissions)}</strong></div><div class="price-row"><span>Vendor proceeds</span><strong>${money(100-state.commissions)}</strong></div></div><button class="btn primary" type="submit">Save commission</button></form></section>`;
return heading+metrics([['Payments collected','$284,650.00','Illustrative marketplace sales','wallet',true],['Vendor payouts','$226,840.00','Paid to vendors','check',true],['Pending payouts','$23,651.20','Next processing cycle','wallet',true],['Platform commission',state.commissions+'%','Default vendor rate','tag',true]])+`<section class="panel"><div class="panel-head"><h2>Vendor payout control</h2><small>Sample payout ledger</small></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Vendor</th><th>Available</th><th>Commission</th><th>Next payout</th><th>Status</th></tr></thead><tbody><tr><td>Tokyo Sound Co.</td><td>$4,860.40</td><td>${state.commissions}%</td><td>October 9, 2026</td><td>${chip('Pending')}</td></tr><tr><td>Maison Aurelle</td><td>$2,430.60</td><td>${state.commissions}%</td><td>October 9, 2026</td><td>${chip('Pending')}</td></tr><tr><td>Nomad Goods</td><td>$3,210.80</td><td>${state.commissions}%</td><td>October 2, 2026</td><td>${chip('Paid')}</td></tr></tbody></table></div></section>`;
}
function vendorTable(list){return `<div class="table-wrap"><table class="data-table"><thead><tr><th>Vendor</th><th>Country</th><th>Category</th><th>Products</th><th>Status</th><th></th></tr></thead><tbody>${list.map(v=>`<tr><td><strong>${esc(v.name)}</strong></td><td>${esc(v.country)}</td><td>${esc(v.category)}</td><td>${v.products}</td><td>${chip(state.vendorStatus[v.id]||v.status)}</td><td>${(state.vendorStatus[v.id]||v.status)==='Pending review'?`<button class="table-action" data-action="review-vendor" data-id="${v.id}">Review application</button>`:'<span style="font-size:12px;color:var(--muted)">Reviewed</span>'}</td></tr>`).join('')||'<tr><td colspan="6">No applications match this view.</td></tr>'}</tbody></table></div>`;}
function account(){return `<main id="main" class="container" style="padding-bottom:55px">${crumbs([['Your account',null]])}<h1 class="page-title">Your little corner of the world.</h1><p class="page-subtitle">Explore your demo orders and saved discoveries. No sign-in required for this prototype.</p><div class="account-grid"><section class="account-panel"><h2>Your demo orders</h2>${state.orders.length?state.orders.map(o=>`<div class="shipping-group"><div><h4>${o.id}</h4><p>${money(o.total)} · ${o.shipments.length} shipments · ${o.status}</p></div><button class="table-action" data-action="order-detail" data-id="${o.id}">View</button></div>`).join(''):'<p>No orders yet. Your demonstration orders will appear here after checkout.</p><a class="btn primary small" href="#shop">Discover something new</a>'}</section><section class="account-panel"><h2>Saved discoveries (${state.wishlist.length})</h2>${state.wishlist.length?`<div class="product-grid">${state.wishlist.map(id=>card(product(id))).join('')}</div>`:'<p>Tap the heart on any product to keep it here for later.</p><a class="text-link" href="#shop">Explore the collection</a>'}</section></div><div class="demo-note" style="margin-top:25px">${icon('info')}Your bag and wishlist are saved on this device. Orders, applications and dashboard changes are temporary and reset when you reload.</div></main>`;}
function help(topic){const content={shipping:['Shipping & delivery','Every vendor, one clear journey.','Orders with products from different vendors are divided into separate shipments. In this prototype, choose an express or economy service and see an estimated shipping fee for each vendor.','The demonstration uses product weight, package dimensions, destination and service level. A production version would obtain live carrier quotes and tracking events through a shipping integration.'],duties:['Duties & taxes','See more of the price before checkout.','The delivered-price estimate includes the product price, a vendor discount, shipping, estimated duties and estimated VAT or sales tax. A vendor duty offset is a discount provided by a seller; it does not remove customs obligations.','All import charges in this prototype use illustrative rates. They are not customs quotes or tax advice. Live calculations would require product classification, actual origin, destination and the selected delivery terms.'],returns:['Returns & refunds','A little help, whenever you need it.','Explore the support and refund flow by opening an order in your demo account, the vendor portal or the admin dashboard. A demo request updates the order status without processing a real refund.','Return eligibility, shipping responsibility, seller policies and cross-border customs handling would be confirmed before launching the marketplace. This prototype does not establish a binding return policy.']};const c=content[topic]||content.shipping;return `<main id="main" class="container"><div class="help-page">${crumbs([[c[0],null]])}<h1>${c[0]}</h1><h2>${c[1]}</h2><p>${c[2]}</p><h2>In this demonstration</h2><p>${c[3]}</p><div class="hero-buttons"><a class="btn primary" href="#shop">Explore the marketplace</a><a class="btn secondary" href="#account">Your demo account</a></div></div></main>`;}
function howPage(){return `<main id="main" class="container" style="padding-bottom:50px">${crumbs([['How it works',null]])}<section class="section" style="padding-top:15px"><div class="eyebrow" style="margin-bottom:17px">A clearer way to shop globally</div><h1 class="page-title">Bring the world home.</h1><p class="page-subtitle">Discover global products and explore an estimate of the complete delivered price.</p>${howContent()}</section><div class="demo-note">${icon('info')}Duty offsets are vendor discounts. Import duties and taxes may still apply. All prices, shipping and tax calculations are illustrative in this prototype.</div><div class="hero-buttons"><a class="btn primary" href="#shop">Explore the marketplace</a><a class="btn secondary" href="#help/duties">About duties & taxes</a></div></main>`;}
function notFound(){return `<main id="main" class="container"><div class="empty-state" style="margin:40px 0">${icon('globe')}<h2>This discovery isn’t here.</h2><p>Return to the marketplace to explore the collection.</p><a class="btn primary" href="#shop">Explore products</a></div></main>`;}
let toastTimer;
function toast(message){const t=document.getElementById('toast');t.textContent=message;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),3200);}
function add(id,qty=1){const p=product(id);if(!p)return;if(p.stock<1){toast('This product is currently out of stock.');return;}const item=state.cart.find(i=>i.id===id);if(item){if(item.qty+qty>Math.min(10,p.stock)){toast('Maximum quantity reached for this item.');return;}item.qty+=qty;}else state.cart.push({id,qty:Math.min(qty,10,p.stock)});save();render(false);window.marketMotion?.feedback('cart');toast(`${esc(p.name)} added to your bag`);}
function render(scroll=false){const parts=location.hash.slice(1).split('/');const route=parts[0]||'home';let content;switch(route){case'home':content=home();break;case'shop':content=catalog();break;case'product':content=detail(parts[1]);break;case'cart':content=cart();break;case'checkout':content=checkout();break;case'confirmation':content=confirmation();break;case'apply':content=apply();break;case'seller':content=dashboardShell();break;case'admin':content=dashboardShell(true);break;case'account':content=account();break;case'how':content=howPage();break;case'help':content=help(parts[1]);break;case'credits':content=credits();break;default:content=notFound();}window.marketMotion?.cleanup();window.dropdownUI?.closeAll();document.getElementById('app').innerHTML=header()+content+footer();window.dropdownUI?.mount();document.title=`${{home:'Shop the world',shop:state.category==='All'?'Discover the world':state.category,product:product(parts[1])?.name||'Product',cart:'Your shopping bag',checkout:'Checkout',confirmation:'Demo order confirmed',apply:'Become a vendor',seller:'Vendor workspace',admin:'Marketplace admin',account:'Your demo account',how:'How it works',help:'Help',credits:'Image credits'}[route]||'Discover'} · DutyFreeDeal`;if(scroll)window.scrollTo({top:0});window.marketMotion?.mount(scroll);}
function routeChanged(){const parts=location.hash.slice(1).split('/');if(parts[0]==='shop'){try{state.category=parts[1]?decodeURIComponent(parts[1]):'All';}catch{state.category='All';}if(!['All',...categories.map(c=>c.name)].includes(state.category))state.category='All';}render(true);}
window.addEventListener('hashchange',routeChanged);
const modal=document.getElementById('modal');
function openModal(content){modal.innerHTML=`<button class="modal-close" data-action="close-modal" aria-label="Close dialog">${icon('close',true)}</button>${content}`;modal.showModal();window.dropdownUI?.mount(modal);window.marketMotion?.dialog();}
modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)modal.close();}});
function newProduct(){openModal(`<h2 class="dialog-title">A new global discovery.</h2><p class="dialog-subtitle">Add your product details and international shipping information. This listing will enter the admin review queue.</p><form id="product-form" class="form-grid"><div class="field full"><label for="new-name">Product name</label><input id="new-name" name="name" required maxlength="100" placeholder="Your product name"></div><div class="field full"><label for="new-desc">Description</label><textarea id="new-desc" name="desc" required maxlength="1500" placeholder="Tell customers what makes it special."></textarea></div><div class="field"><label for="new-category">Category</label><select id="new-category" name="category">${categories.map(c=>`<option>${c.name}</option>`).join('')}</select></div><div class="field"><label for="new-origin">Country of origin</label><input id="new-origin" name="origin" required maxlength="60" placeholder="Japan"></div><div class="field"><label for="new-price">Selling price (USD)</label><input id="new-price" name="price" type="number" min="1" max="100000" step=".01" required placeholder="100.00"></div><div class="field"><label for="new-discount">Duty offset discount (USD)</label><input id="new-discount" name="discount" type="number" min="0" step=".01" value="0" required></div><div class="field"><label for="new-sku">SKU</label><input id="new-sku" name="sku" required maxlength="50" placeholder="TS-PRODUCT-001"></div><div class="field"><label for="new-stock">Inventory</label><input id="new-stock" name="stock" type="number" min="1" max="999999" step="1" required placeholder="50"></div><div class="field"><label for="new-weight">Package weight (kg)</label><input id="new-weight" name="weight" type="number" min=".01" max="1000" step=".01" required placeholder="0.50"></div><div class="field"><label for="new-hs">HS commodity code</label><input id="new-hs" name="hs" pattern="[0-9]{6,10}" maxlength="10" required placeholder="6–10 digits"><small>For product classification in international shipping.</small></div><div class="field full"><label>Package dimensions (cm)</label><div class="form-grid" style="grid-template-columns:1fr 1fr 1fr;gap:10px">${['length','width','height'].map(n=>`<input type="number" name="${n}" min="1" max="500" required placeholder="${n[0].toUpperCase()+n.slice(1)}" aria-label="Package ${n} in centimeters">`).join('')}</div></div><div class="upload-zone">${icon('upload')}<span>Product photo</span><input type="file" id="product-photo" name="photo" accept="image/jpeg,image/png,image/webp" aria-label="Product photo"><small style="font-size:12px;color:var(--muted)">Optional · JPEG, PNG or WebP · maximum 5 MB · session only</small><div id="photo-preview"></div></div><div class="field full"><label for="new-color">Finish / variant</label><input id="new-color" name="color" maxlength="50" placeholder="Black"></div><div class="dialog-actions field full"><button type="button" class="btn secondary" data-action="close-modal">Cancel</button><button class="btn primary" type="submit">Submit for review</button></div></form>`);}
let uploadPreview='';
function allOrders(){return [...state.orders,...demoOrders];}
function orderDialog(id){const o=allOrders().find(o=>o.id===id);if(!o)return;const items=o.items||o.shipments.flatMap(s=>s.items.map(p=>({id:p.id,qty:p.qty})));openModal(`<h2 class="dialog-title">Order ${esc(o.id)}</h2><p class="dialog-subtitle">${esc(o.customer)} · ${esc(o.country)} · ${o.date}</p><div class="order-line"><span>Order status</span>${chip(o.status)}</div><div class="order-line"><span>Collected total · demo</span><strong>${money(o.total)}</strong></div>${items.map(i=>`<div class="order-line"><span>${esc(product(i.id)?.name||'Product')} × ${i.qty}</span><strong>${money(net(product(i.id))*i.qty)}</strong></div>`).join('')}<div class="order-line"><span>Shipment tracking</span><strong>${esc(o.tracking||'DFD-DEMO · Awaiting shipment')}</strong></div><p class="summary-note">${icon('info')}Tracking, customer support and refunds are simulated. No messages or funds are sent.</p><div class="dialog-actions"><button class="btn secondary small" data-action="order-support" data-id="${o.id}">Contact support</button>${o.status!=='Refunded'&&(o.status!=='Refund requested'||location.hash.startsWith('#admin'))?`<button class="btn primary small" data-action="refund-start" data-id="${o.id}">${location.hash.startsWith('#admin')?'Review refund':'Request a refund'}</button>`:''}</div>`);}
document.addEventListener('submit',e=>{
 const f=e.target;const data=new FormData(f);if(f.id==='search-form'){e.preventDefault();state.search=String(data.get('search')).trim();state.category='All';state.origin='All';state.maxPrice=Infinity;if(location.hash==='#shop')render(true);else location.hash='shop';}
 if(f.id==='checkout-form'){e.preventDefault();if(!state.cart.length||state.cart.some(i=>!product(i.id)||i.qty<1||i.qty>product(i.id).stock)){toast('Please review availability in your bag.');location.hash='cart';return;}const t=estimate(state.cart);const o={id:`DFD-DEMO-${String(state.orders.length+1).padStart(3,'0')}`,name:String(data.get('firstName')),customer:`${data.get('firstName')} ${data.get('lastName')}`,country:`${countries[state.destination].flag} ${countries[state.destination].name}`,date:'Oct 6, 2026',total:t.total,status:'Processing',shipments:t.shipments,items:state.cart.map(i=>({...i})),service:state.delivery,tracking:'DFD-DEMO · Awaiting shipment'};state.order=o;state.orders.unshift(o);state.cart=[];save();location.hash='confirmation';}
 if(f.id==='apply-form'){e.preventDefault();state.application=Object.fromEntries(data);state.submitted=true;render(true);}
 if(f.id==='commission-form'){e.preventDefault();state.commissions=Number(data.get('commission'));render();toast(`Default commission saved: ${state.commissions}%`);}
 if(f.id==='stock-form'){e.preventDefault();const p=product(f.dataset.id)||state.extraProducts.find(p=>p.id===f.dataset.id);p.stock=Number(data.get('stock'));state.cart=state.cart.map(i=>i.id===p.id?{...i,qty:Math.min(i.qty,p.stock)}:i).filter(i=>i.qty>0);save();modal.close();render();toast('Demo inventory updated');}
 if(f.id==='product-form'){e.preventDefault();const d=Object.fromEntries(data);if(Number(d.discount)>=Number(d.price)){f.querySelector('#new-discount').setCustomValidity('Discount must be less than the selling price.');f.querySelector('#new-discount').reportValidity();return;}const id='custom-'+(state.extraProducts.length+1);const category=categories.find(c=>c.name===d.category);const p={id,custom:true,name:d.name,brand:state.application?.business||'Tokyo Sound Co.',category:d.category,country:d.origin,flag:'🌐',code:({Japan:'JP',France:'FR',Italy:'IT',Germany:'DE',Switzerland:'CH',Portugal:'PT',Denmark:'DK','United States':'US','United Kingdom':'GB','United Arab Emirates':'AE',Canada:'CA'})[d.origin]||'OTHER',vendor:state.application?.business||'Tokyo Sound Co.',price:Number(d.price),discount:Number(d.discount),stock:Number(d.stock),weight:Number(d.weight),dimensions:`${d.length} × ${d.width} × ${d.height} cm`,sku:d.sku,hs:d.hs,desc:d.desc,color:d.color||'Original',image:category.image,photo:uploadPreview,rating:5,reviews:0};state.extraProducts.unshift(p);uploadPreview='';modal.close();state.dashboard='products';state.tableSearch='';state.tableStatus='All';render();toast('Product submitted. Review it in the admin dashboard.');}
 if(f.id==='support-form'){e.preventDefault();modal.close();toast('Demo support request saved. No message was sent.');}
});
document.addEventListener('input',e=>{if(e.target.id==='new-discount'||e.target.id==='new-price')document.getElementById('new-discount').setCustomValidity('');});
document.addEventListener('change',async e=>{
 const el=e.target;if(el.id==='destination'||el.id==='summary-destination'){state.destination=el.value;save();if(location.hash==='#checkout'){const form=document.getElementById('checkout-form');const fields=form?Object.fromEntries(new FormData(form)):{};render();for(const [name,value]of Object.entries(fields)){const target=document.querySelector(`#checkout-form [name="${name}"]`);if(target)target.value=value;}}else render();toast(`Delivery estimates updated for ${countries[state.destination].name}`);}
 if(el.name==='origin'){state.origin=el.value;render();}if(el.id==='price-range'){state.maxPrice=Number(el.value)>=priceCap()?Infinity:Number(el.value);render();}if(el.id==='sort'){state.sort=el.value;render();}if(el.name==='delivery'){state.delivery=el.value;render();}if(el.id==='table-status'){state.tableStatus=el.value;render();}if(el.id==='table-search'){state.tableSearch=el.value;render();}
 if(el.id==='product-photo'){const file=el.files[0];if(!file){uploadPreview='';return;}if(file.size>5*1024*1024||!['image/jpeg','image/png','image/webp'].includes(file.type)){toast('Choose a JPEG, PNG or WebP image under 5 MB.');el.value='';return;}const reader=new FileReader();reader.onload=()=>{uploadPreview=reader.result;document.getElementById('photo-preview').innerHTML=`<img src="${uploadPreview}" alt="Uploaded product preview">`;};reader.readAsDataURL(file);}
});
document.addEventListener('click',e=>{
 const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=b.dataset.id;
 if(a==='add')add(id);
 if(a==='wish'){state.wishlist=state.wishlist.includes(id)?state.wishlist.filter(x=>x!==id):[...state.wishlist,id];save();render();window.marketMotion?.feedback('wish',id);toast(state.wishlist.includes(id)?'Saved to your wishlist':'Removed from your wishlist');}
 if(a==='filter-category'){state.category=b.dataset.value;location.hash=state.category==='All'?'shop':`shop/${encodeURIComponent(state.category)}`;render();}
 if(a==='reset-filters'){state.category='All';state.origin='All';state.maxPrice=Infinity;state.search='';state.sort='featured';location.hash='shop';render();}
 if(a==='detail-qty'){const input=document.getElementById('detail-quantity');input.value=Math.min(10,Math.max(1,Number(input.value)+Number(b.dataset.delta)));}
 if(a==='detail-add'){const input=document.getElementById('detail-quantity');if(!input.checkValidity()){input.reportValidity();return;}add(id,Number(input.value));}
 if(a==='cart-qty'){const item=state.cart.find(i=>i.id===id);if(item){item.qty=Math.min(10,product(id).stock,Math.max(1,item.qty+Number(b.dataset.delta)));save();render();}}
 if(a==='remove'){state.cart=state.cart.filter(i=>i.id!==id);save();render();toast('Item removed from your bag');}
 if(a==='close-modal')modal.close();
 if(a==='dashboard-tab'){state[b.dataset.admin==='true'?'adminTab':'dashboard']=b.dataset.value;state.tableSearch='';state.tableStatus='All';render();window.marketMotion?.mount(true);}
 if(a==='new-product'){uploadPreview='';newProduct();}
 if(a==='edit-stock'){const p=product(id)||state.extraProducts.find(p=>p.id===id);openModal(`<h2 class="dialog-title">Update inventory</h2><p class="dialog-subtitle">${esc(p.name)} · ${esc(p.sku)}</p><form id="stock-form" data-id="${id}"><div class="field"><label for="stock">Available inventory</label><input type="number" name="stock" id="stock" value="${p.stock}" min="0" max="999999" step="1" required></div><div class="dialog-actions"><button type="button" class="btn secondary" data-action="close-modal">Cancel</button><button class="btn primary">Save inventory</button></div></form>`);}
 if(a==='request-payout'){state.payoutRequested=true;render();toast('Demo payout scheduled. No funds are transferred.');}
 if(a==='review-vendor'){const v=id==='new-vendor'?{name:state.application.business,country:state.application.country,category:state.application.category,about:state.application.about}:vendors.find(v=>v.id===id);openModal(`<h2 class="dialog-title">Review vendor application</h2><p class="dialog-subtitle">Confirm this vendor before enabling their demo workspace.</p><div class="order-line"><span>Business</span><strong>${esc(v.name)}</strong></div><div class="order-line"><span>Country</span><strong>${esc(v.country)}</strong></div><div class="order-line"><span>Category</span><strong>${esc(v.category)}</strong></div>${v.about?`<p class="page-subtitle" style="margin-top:18px">${esc(v.about)}</p>`:''}<div class="dialog-actions"><button class="btn secondary" data-action="vendor-decision" data-id="${id}" data-value="Rejected">Reject</button><button class="btn primary" data-action="vendor-decision" data-id="${id}" data-value="Approved">Approve vendor</button></div>`);}
 if(a==='vendor-decision'){state.vendorStatus[id]=b.dataset.value;modal.close();render();toast(`Demo vendor ${b.dataset.value.toLowerCase()}`);}
 if(a==='review-product'){const p=state.extraProducts.find(p=>p.id===id);openModal(`<h2 class="dialog-title">Review product listing</h2><p class="dialog-subtitle">${esc(p.name)} · ${esc(p.sku)}</p>${p.photo?`<img src="${p.photo}" alt="Uploaded product" style="height:100px;object-fit:contain;margin-bottom:15px">`:''}<p class="page-subtitle">${esc(p.desc)}</p><div class="order-line"><span>Product price / duty offset</span><strong>${money(p.price)} / ${money(p.discount)}</strong></div><div class="order-line"><span>Inventory</span><strong>${p.stock} units</strong></div><div class="order-line"><span>Origin / HS code</span><strong>${esc(p.country)} / ${esc(p.hs)}</strong></div><div class="order-line"><span>Weight / dimensions</span><strong>${p.weight} kg / ${esc(p.dimensions)}</strong></div><div class="dialog-actions"><button class="btn secondary" data-action="product-decision" data-id="${id}" data-value="Rejected">Reject listing</button><button class="btn primary" data-action="product-decision" data-id="${id}" data-value="Approved">Approve listing</button></div>`);}
 if(a==='product-decision'){state.productStatus[id]=b.dataset.value;const p=state.extraProducts.find(p=>p.id===id);if(b.dataset.value==='Approved'&&!product(id))products.push(p);modal.close();render();toast(b.dataset.value==='Approved'?'Product approved and visible in the marketplace':'Demo listing rejected');}
 if(a==='order-detail')orderDialog(id);
 if(a==='order-support'){openModal(`<h2 class="dialog-title">How can we help?</h2><p class="dialog-subtitle">Demo support request for ${esc(id)}. No message will be sent.</p><form id="support-form"><div class="field"><label for="support-message">Your message</label><textarea id="support-message" required maxlength="1500" placeholder="Tell us what you need help with."></textarea></div><div class="dialog-actions"><button class="btn primary">Save demo request</button></div></form>`);}
 if(a==='refund-start'){openModal(`<h2 class="dialog-title">${location.hash.startsWith('#admin')?'Approve a demo refund':'Request a demo refund'}</h2><p class="dialog-subtitle">Order ${esc(id)}. This updates the demonstration order status only.</p><div class="demo-note">${icon('info')}No refund is issued and no funds are moved. In a live marketplace, eligibility and seller return terms would be checked first.</div><div class="dialog-actions"><button class="btn secondary" data-action="close-modal">Cancel</button><button class="btn primary" data-action="refund-confirm" data-id="${id}" data-value="${location.hash.startsWith('#admin')?'Refunded':'Refund requested'}">${location.hash.startsWith('#admin')?'Approve demo refund':'Submit demo request'}</button></div>`);}
 if(a==='refund-confirm'){const o=allOrders().find(o=>o.id===id);o.status=b.dataset.value;modal.close();render();toast(b.dataset.value==='Refunded'?'Demo refund approved':'Demo refund request recorded');}
});
