function registerWebMCP(){const context=document.modelContext;if(!context?.registerTool)return;const lifecycle=new AbortController();const definitions=[{name:'search_marketplace',title:'Search DutyFreeDeal',description:'Navigate to demo catalog results matching a query.',inputSchema:{type:'object',properties:{query:{type:'string',maxLength:200}},required:['query'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(typeof input?.query!=='string'||input.query.length>200)throw new Error('A query under 200 characters is required.');state.search=input.query;state.category='All';state.origin='All';state.maxPrice=Infinity;location.hash='shop';render();return{query:state.search,matches:products.filter(p=>`${esc(p.name)} ${esc(p.brand)} ${esc(p.country)}`.toLowerCase().includes(state.search.toLowerCase())).map(p=>({id:p.id,name:p.name,price:net(p)}))};}},{name:'read_demo_bag',title:'Read demo shopping bag',description:'Read current demo bag items and the illustrative delivered-price estimate.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute(){return{items:state.cart.map(i=>({...i,name:product(i.id).name})),destination:countries[state.destination].name,...estimate(state.cart)};}},{name:'add_demo_bag_item',title:'Add product to demo bag',description:'Add a product and quantity to the device-local demo shopping bag. Does not place an order or process payment.',inputSchema:{type:'object',properties:{productId:{type:'string'},quantity:{type:'integer',minimum:1,maximum:10}},required:['productId','quantity'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!product(input?.productId)||!Number.isInteger(input.quantity)||input.quantity<1||input.quantity>10)throw new Error('A valid product ID and quantity from 1 to 10 are required.');const previous=state.cart.find(i=>i.id===input.productId)?.qty||0;if(previous+input.quantity>Math.min(10,product(input.productId).stock))throw new Error('Requested quantity exceeds available demo inventory.');add(input.productId,input.quantity);return{items:cartCount(),estimate:estimate(state.cart).total};}}];for(const definition of definitions)try{Promise.resolve(context.registerTool(definition,{signal:lifecycle.signal})).catch(()=>{});}catch{}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
registerWebMCP();
routeChanged();
